INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Vergibt ein IPv4-DHCP-Server automatisch IP-Adressen an Clients?', 2, '[{"text": "Ja", "correct": true, "because": "Das ist die Hauptfunktion von DHCP"}, {"text": "Nein", "correct": false, "because": "Automatische Vergabe ist Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist DHCPv6 zwingend erforderlich, um IPv6-Adressen zu konfigurieren?', 2, '[{"text": "Nein", "correct": true, "because": "SLAAC kann auch IPv6-Adressen zuweisen"}, {"text": "Ja", "correct": false, "because": "SLAAC ist eine Alternative"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein IPv4-DHCP-Server auch Subnetzmasken verteilen?', 2, '[{"text": "Ja", "correct": true, "because": "Subnetzmasken sind Teil der DHCP-Konfiguration"}, {"text": "Nein", "correct": false, "because": "Subnetzmaske wird mitgeliefert"}]'),
('00000000-0000-0000-0000-000000000000', 'Unterstützt DHCPv6 die gleichen Optionen wie IPv4-DHCP?', 2, '[{"text": "Nein", "correct": true, "because": "DHCPv6 hat andere Optionen, z. B. keine Gateway-Adresse"}, {"text": "Ja", "correct": false, "because": "Unterschiede bestehen"}]'),
('00000000-0000-0000-0000-000000000000', 'Nutzt IPv4-DHCP den DORA-Prozess für die Adressvergabe?', 2, '[{"text": "Ja", "correct": true, "because": "Discover, Offer, Request, Acknowledge ist der Prozess"}, {"text": "Nein", "correct": false, "because": "DORA ist Standard"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Port wird von einem IPv4-DHCP-Client verwendet, um Anfragen zu senden?', 2, '[{"text": "68", "correct": true, "because": "Port 68 ist für DHCP-Clients"}, {"text": "67", "correct": false, "because": "Port 67 ist für Server"}, {"text": "80", "correct": false, "because": "Das ist HTTP"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist der Hauptunterschied zwischen DHCPv6 und SLAAC bei der IPv6-Adressvergabe?', 3, '[{"text": "DHCPv6 ist stateful, SLAAC stateless", "correct": true, "because": "DHCPv6 speichert Zustände, SLAAC nicht"}, {"text": "SLAAC nutzt einen Server", "correct": false, "because": "SLAAC ist serverlos"}, {"text": "DHCPv6 ist schneller", "correct": false, "because": "SLAAC ist oft schneller"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse wird von einem IPv4-DHCP-Server als Broadcast verwendet?', 2, '[{"text": "255.255.255.255", "correct": true, "because": "Broadcast-Adresse für DHCP"}, {"text": "192.168.1.1", "correct": false, "because": "Das ist ein Gateway"}, {"text": "0.0.0.0", "correct": false, "because": "Das ist die Client-Anfrage"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche zusätzliche Information kann DHCPv6 im Vergleich zu SLAAC liefern?', 2, '[{"text": "DNS-Server-Adresse", "correct": true, "because": "DHCPv6 liefert DNS, SLAAC nicht"}, {"text": "Netzwerkpräfix", "correct": false, "because": "SLAAC liefert das auch"}, {"text": "MAC-Adresse", "correct": false, "because": "Das hat der Client bereits"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Schritt im IPv4-DHCP-Prozess bestätigt die Adressvergabe?', 2, '[{"text": "Acknowledge (ACK)", "correct": true, "because": "ACK ist der letzte Schritt im DORA"}, {"text": "Offer", "correct": false, "because": "Offer ist nur ein Angebot"}, {"text": "Discover", "correct": false, "because": "Discover ist die Anfrage"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Informationen vergibt ein IPv4-DHCP-Server?', 4, '[{"text": "IP-Adresse", "correct": true, "because": "Hauptfunktion von DHCP"}, {"text": "Subnetzmaske", "correct": true, "because": "Definiert Netzwerkgröße"}, {"text": "Standard-Gateway", "correct": true, "because": "Für Routing nötig"}, {"text": "MAC-Adresse", "correct": false, "because": "Client-seitig vorhanden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zum IPv4-DHCP-DORA-Prozess?', 3, '[{"text": "Discover", "correct": true, "because": "Client sucht Server"}, {"text": "Offer", "correct": true, "because": "Server bietet Adresse"}, {"text": "Request", "correct": true, "because": "Client fordert Adresse"}, {"text": "Handshake", "correct": false, "because": "Kein TCP-Handshake"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet DHCPv6 gegenüber SLAAC?', 4, '[{"text": "Zentrale Verwaltung", "correct": true, "because": "Stateful Kontrolle"}, {"text": "DNS-Server-Zuweisung", "correct": true, "because": "Zusätzliche Optionen"}, {"text": "Schnellere Konfiguration", "correct": false, "because": "SLAAC ist schneller"}, {"text": "Mehr Konfigurationsoptionen", "correct": true, "because": "z. B. NTP"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten sind für die DHCP-Einrichtung nötig?', 3, '[{"text": "DHCP-Server", "correct": true, "because": "Vergibt Adressen"}, {"text": "DHCP-Client", "correct": true, "because": "Empfängt Adressen"}, {"text": "Router mit Relay-Agent", "correct": true, "because": "Leitet Anfragen weiter"}, {"text": "WLAN-Access-Point", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Unterschiede gibt es zwischen IPv4-DHCP und DHCPv6?', 3, '[{"text": "IPv4-DHCP vergibt Gateway, DHCPv6 nicht", "correct": true, "because": "Gateway via RA bei IPv6"}, {"text": "DHCPv6 unterstützt 128-Bit-Adressen", "correct": true, "because": "IPv6-Adressen"}, {"text": "IPv4-DHCP ist schneller", "correct": false, "because": "Kein signifikanter Unterschied"}, {"text": "DHCPv6 kann DNS liefern", "correct": true, "because": "Zusatzoption"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) IPv4-DHCP nutzt den DORA-Prozess. b) DHCPv6 ist immer schneller als SLAAC.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "DORA ja, SLAAC oft schneller"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DHCPv6 kann DNS-Server zuweisen. b) IPv4-DHCP ist für IPv6-Adressen geeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "DNS ja, IPv4-DHCP nicht für IPv6"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) IPv4-DHCP vergibt Subnetzmasken. b) DHCPv6 benötigt keinen Server.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Subnetzmaske ja, DHCPv6 braucht Server"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) IPv4-DHCP nutzt Port 67 für den Server. b) DHCPv6 ist stateless.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Port 67 ja, DHCPv6 ist stateful"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) DHCPv6 kann mit SLAAC kombiniert werden. b) IPv4-DHCP vergibt 128-Bit-Adressen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kombination möglich, IPv4 nur 32 Bit"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

